using System.Text;
using RecursiveAI.OneDocument.Documents.Numbering;
using RecursiveAI.OneDocument.Packaging;

namespace RecursiveAI.OneDocument.Documents.Tests;

// The expected labels are what Word 16.0.20527 gave for the same documents (generated by tools/office-oracle/make-story-cases.py).
public class StoryLabelTests
{
    private const string W = TestDocs.WNs;
    private const string Wps = "http://schemas.microsoft.com/office/word/2010/wordprocessingShape";
    private const string Mc = "http://schemas.openxmlformats.org/markup-compatibility/2006";
    private const string V = "urn:schemas-microsoft-com:vml";
    private const string Ns = $"xmlns:w=\"{W}\" xmlns:r=\"{TestDocs.RNs}\" xmlns:wps=\"{Wps}\" xmlns:mc=\"{Mc}\" xmlns:v=\"{V}\"";

    private const string Numbering =
        "<w:abstractNum w:abstractNumId=\"0\"><w:lvl w:ilvl=\"0\"><w:start w:val=\"1\"/><w:numFmt w:val=\"decimal\"/><w:lvlText w:val=\"%1.\"/></w:lvl></w:abstractNum>" +
        "<w:abstractNum w:abstractNumId=\"1\"><w:lvl w:ilvl=\"0\"><w:start w:val=\"1\"/><w:numFmt w:val=\"lowerLetter\"/><w:lvlText w:val=\"(%1)\"/></w:lvl></w:abstractNum>" +
        "<w:num w:numId=\"1\"><w:abstractNumId w:val=\"0\"/></w:num><w:num w:numId=\"2\"><w:abstractNumId w:val=\"1\"/></w:num>";

    private static string Np(string tag, int num = 1) =>
        $"<w:p><w:pPr><w:numPr><w:ilvl w:val=\"0\"/><w:numId w:val=\"{num}\"/></w:numPr></w:pPr><w:r><w:t>{tag}</w:t></w:r></w:p>";

    private static string Plain(string tag) => $"<w:p><w:r><w:t>{tag}</w:t></w:r></w:p>";

    private static void Add(InMemoryPackage p, string name, string suffix, string relType, string id, string xml)
    {
        p.AddPart(name, "application/vnd.openxmlformats-officedocument.wordprocessingml." + suffix, Encoding.UTF8.GetBytes("<?xml version=\"1.0\" encoding=\"UTF-8\"?>" + xml));
        var rels = new List<Relationship>(p.GetRelationships("/word/document.xml"))
        {
            new(id, PartHelper.Rel + relType, name["/word/".Length..]),
        };
        p.SetRelationships("/word/document.xml", rels);
    }

    private static Document Open(string body, Action<InMemoryPackage>? parts = null, string? settings = null)
    {
        InMemoryPackage p = TestDocs.Package("", null, Numbering);
        p.FindPart("/word/document.xml")!.SetBytes(Encoding.UTF8.GetBytes($"<w:document {Ns}><w:body>{body}</w:body></w:document>"));
        if (settings is not null)
        {
            Add(p, "/word/settings.xml", "settings+xml", "settings", "rIdSet", $"<w:settings xmlns:w=\"{W}\">{settings}</w:settings>");
        }

        parts?.Invoke(p);
        return Document.FromPackage(p);
    }

    private static string[] Flat(Document d, StoryKind kind) =>
        d.Numbering.LabelStories().Where(s => s.Kind == kind).SelectMany(s => s.Labels).Select(l => l.Paragraph.Text + "=" + l.Text).ToArray();

    [Fact]
    public void HeadersAndFootersFormOneFlowSeparateFromTheBody()
    {
        string refs1 = "<w:headerReference w:type=\"default\" r:id=\"rH1\"/><w:headerReference w:type=\"first\" r:id=\"rH2\"/><w:headerReference w:type=\"even\" r:id=\"rH3\"/><w:footerReference w:type=\"default\" r:id=\"rF1\"/>";
        string refs2 = "<w:headerReference w:type=\"default\" r:id=\"rH4\"/><w:footerReference w:type=\"default\" r:id=\"rF2\"/>";
        using Document d = Open(
            Np("b1") + Np("b2") + $"<w:p><w:pPr><w:sectPr>{refs1}<w:titlePg/></w:sectPr></w:pPr><w:r><w:t>end</w:t></w:r></w:p>" + Np("b3") + Np("b4") + $"<w:sectPr>{refs2}</w:sectPr>",
            p =>
            {
                Add(p, "/word/header1.xml", "header+xml", "header", "rH1", $"<w:hdr {Ns}>{Np("hd1")}{Np("hd2")}{Np("hd3")}</w:hdr>");
                Add(p, "/word/header2.xml", "header+xml", "header", "rH2", $"<w:hdr {Ns}>{Np("hf1")}{Np("hf2")}</w:hdr>");
                Add(p, "/word/header3.xml", "header+xml", "header", "rH3", $"<w:hdr {Ns}>{Np("he1")}{Np("he2")}</w:hdr>");
                Add(p, "/word/header4.xml", "header+xml", "header", "rH4", $"<w:hdr {Ns}>{Np("h2a")}{Np("h2b")}</w:hdr>");
                Add(p, "/word/footer1.xml", "footer+xml", "footer", "rF1", $"<w:ftr {Ns}>{Np("fd1")}{Np("fd2")}</w:ftr>");
                Add(p, "/word/footer2.xml", "footer+xml", "footer", "rF2", $"<w:ftr {Ns}>{Np("f2a")}{Np("f2b")}</w:ftr>");
            },
            "<w:evenAndOddHeaders/>");

        Assert.Equal(["b1=1.", "b2=2.", "b3=3.", "b4=4."], Flat(d, StoryKind.Body));
        // Word: even header 1-2, default header 3-5, default footer 6-7, first header 8-9, then the second section: header 10-11, footer 12-13.
        string[] all = d.Numbering.LabelStories().Where(s => s.Kind is StoryKind.Header or StoryKind.Footer).SelectMany(s => s.Labels)
            .Select(l => l.Paragraph.Text + "=" + l.Text).ToArray();
        Assert.Equal(["he1=1.", "he2=2.", "hd1=3.", "hd2=4.", "hd3=5.", "fd1=6.", "fd2=7.", "hf1=8.", "hf2=9.", "h2a=10.", "h2b=11.", "f2a=12.", "f2b=13."], all);
    }

    [Fact]
    public void FootnotesAndEndnotesEachCountAcrossTheirNotes()
    {
        string sep = "<w:footnote w:type=\"separator\" w:id=\"-1\"><w:p><w:r><w:separator/></w:r></w:p></w:footnote>";
        string fn = $"<w:footnotes {Ns}>{sep}<w:footnote w:id=\"1\">{Np("fn1a")}{Np("fn1b")}</w:footnote><w:footnote w:id=\"2\">{Np("fn2a")}{Plain("fn2plain")}{Np("fn2b")}</w:footnote><w:footnote w:id=\"3\">{Np("fn3a", 2)}{Np("fn3b")}</w:footnote></w:footnotes>";
        string en = $"<w:endnotes {Ns}><w:endnote w:id=\"1\">{Np("en1a")}{Np("en1b")}</w:endnote><w:endnote w:id=\"2\">{Np("en2a")}</w:endnote></w:endnotes>";
        using Document d = Open(Np("b1") + Np("b2") + Np("b3"), p =>
        {
            Add(p, "/word/footnotes.xml", "footnotes+xml", "footnotes", "rFn", fn);
            Add(p, "/word/endnotes.xml", "endnotes+xml", "endnotes", "rEn", en);
        });
        Assert.Equal(["fn1a=1.", "fn1b=2.", "fn2a=3.", "fn2b=4.", "fn3a=(a)", "fn3b=5."], Flat(d, StoryKind.Footnotes));
        Assert.Equal(["en1a=1.", "en1b=2.", "en2a=3."], Flat(d, StoryKind.Endnotes));
        Assert.Equal(["b1=1.", "b2=2.", "b3=3."], Flat(d, StoryKind.Body));
    }

    [Fact]
    public void CommentsCountAcrossComments()
    {
        string cm = $"<w:comments {Ns}><w:comment w:id=\"0\" w:author=\"P\">{Np("cm1a")}{Np("cm1b")}</w:comment><w:comment w:id=\"1\" w:author=\"P\">{Np("cm2a")}</w:comment></w:comments>";
        using Document d = Open(Np("b1") + Np("b2"), p => Add(p, "/word/comments.xml", "comments+xml", "comments", "rCm", cm));
        Assert.Equal(["cm1a=1.", "cm1b=2.", "cm2a=3."], Flat(d, StoryKind.Comments));
    }

    private static string DmlBox(string a, string b) =>
        $"<w:r><mc:AlternateContent><mc:Choice Requires=\"wps\"><w:drawing><wps:wsp><wps:txbx><w:txbxContent>{Np(a)}{Np(b)}</w:txbxContent></wps:txbx></wps:wsp></w:drawing></mc:Choice>" +
        $"<mc:Fallback><w:pict><v:shape><v:textbox><w:txbxContent>{Np(a)}{Np(b)}</w:txbxContent></v:textbox></v:shape></w:pict></mc:Fallback></mc:AlternateContent></w:r>";

    private static string VmlBox(string a, string b) =>
        $"<w:r><w:pict><v:shape><v:textbox><w:txbxContent>{Np(a)}{Np(b)}</w:txbxContent></v:textbox></v:shape></w:pict></w:r>";

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void TextBoxesCountAsOneFlowOfTheirOwn(bool drawing)
    {
        Func<string, string, string> box = drawing ? DmlBox : VmlBox;
        string Anchor(string tag, string boxes) =>
            $"<w:p><w:pPr><w:numPr><w:ilvl w:val=\"0\"/><w:numId w:val=\"1\"/></w:numPr></w:pPr><w:r><w:t>{tag}</w:t></w:r>{boxes}</w:p>";
        using Document d = Open(Anchor("b1", box("t1a", "t1b")) + Anchor("b2", box("t2a", "t2b")) + Np("b3"));
        // Word: body 1-3; the boxes continue each other, 1-4, and the fallback copy is not counted twice.
        Assert.Equal(["b1=1.", "b2=2.", "b3=3."], Flat(d, StoryKind.Body));
        Assert.Equal(["t1a=1.", "t1b=2.", "t2a=3.", "t2b=4."], Flat(d, StoryKind.TextBox));
    }

    [Fact]
    public void LabelOfFindsParagraphsInEveryStory()
    {
        using Document d = Open(Np("b1") + DmlParagraph());
        Paragraph inBox = d.TextBoxes()[0].Paragraphs().Last();
        Assert.Equal("2.", d.Numbering.LabelOf(inBox)?.Text);
        Assert.Equal("1.", d.Numbering.LabelOf(d.Body.Paragraphs().First())?.Text);

        static string DmlParagraph() => $"<w:p>{DmlBox("x", "y")}</w:p>";
    }

    [Fact]
    public void ExtractionPrefixesLabelsInHeadersNotesAndTextBoxes()
    {
        string fn = $"<w:footnotes {Ns}><w:footnote w:id=\"1\">{Np("note one")}</w:footnote></w:footnotes>";
        using Document d = Open($"<w:p><w:r><w:t>body</w:t></w:r></w:p><w:p>{DmlBox("boxed", "again")}</w:p>", p => Add(p, "/word/footnotes.xml", "footnotes+xml", "footnotes", "rFn", fn));
        RecursiveAI.OneDocument.TextExtraction.IListLabelSource labels = DocumentText.ListLabels(d);
        Assert.Equal("1.\t", labels.LabelFor("/word/footnotes.xml", d.Footnotes[d.Footnotes.Count - 1].Paragraphs().First().Markup.Node.SourceStart));
        Paragraph boxed = d.TextBoxes()[0].Paragraphs().First();
        Assert.Equal("1.\t", labels.LabelFor("/word/document.xml", boxed.Markup.Node.SourceStart));
        Assert.Null(labels.LabelFor("/word/document.xml", d.Body.Paragraphs().First().Markup.Node.SourceStart));
    }
}
